import type { Skill } from '@wener/ai/agent/skill';
import type { IFileSystem } from '@wener/common/fs';

export type AgentWorkspace = {
	id: string;
	fileSystem: IFileSystem;
	rootPath: string;
	label?: string;
	revision?: number | string;
};

export type AgentWorkspaceContextLimits = {
	maxAgentsBytes: number;
	maxAggregateBytes: number;
	maxSkillBytes: number;
	maxSkills: number;
};

export const defaultAgentWorkspaceContextLimits: Readonly<AgentWorkspaceContextLimits> = Object.freeze({
	maxAgentsBytes: 64 * 1024,
	maxAggregateBytes: 256 * 1024,
	maxSkillBytes: 32 * 1024,
	maxSkills: 32,
});

export type AgentWorkspaceContextIssue = {
	code:
		| 'aborted'
		| 'agents-read-failed'
		| 'agents-too-large'
		| 'aggregate-too-large'
		| 'invalid-text'
		| 'skill-count-exceeded'
		| 'skill-too-large';
	message: string;
	path?: string;
	skillIdentity?: string;
	skillName?: string;
};

export type AgentWorkspaceAgentsContext = {
	bytes: number;
	content: string;
	path: string;
};

export type AgentWorkspaceSkillContext = Pick<Skill, 'description' | 'instructions' | 'name' | 'version'> & {
	bytes: number;
	identity: string;
};

export type AgentWorkspaceContext = {
	agents?: AgentWorkspaceAgentsContext;
	bytes: number;
	issues: AgentWorkspaceContextIssue[];
	skills: AgentWorkspaceSkillContext[];
	workspaceId: string;
	workspaceRevision?: number | string;
};

export type LoadAgentWorkspaceContextOptions = {
	agentsPath?: string;
	limits?: Partial<AgentWorkspaceContextLimits>;
	signal?: AbortSignal;
	skills: readonly Skill[];
	workspace: AgentWorkspace;
};

const maxWorkspacePathBytes = 4096;
const maxWorkspaceNameBytes = 255;

export class AgentWorkspacePathError extends Error {
	constructor(
		message: string,
		readonly code: 'invalid-name' | 'invalid-path' | 'outside-root',
	) {
		super(message);
		this.name = 'AgentWorkspacePathError';
	}
}

export function normalizeAgentWorkspaceRoot(rootPath: string): string {
	if (!rootPath.startsWith('/')) throw new AgentWorkspacePathError('工作区根路径必须是绝对路径。', 'invalid-path');
	return normalizeAbsolutePath(rootPath);
}

export function resolveAgentWorkspacePath(rootPath: string, inputPath: string): string {
	const root = normalizeAgentWorkspaceRoot(rootPath);
	if (!inputPath || utf8Bytes(inputPath) > maxWorkspacePathBytes || inputPath.includes('\0')) {
		throw new AgentWorkspacePathError('工作区路径无效或过长。', 'invalid-path');
	}
	const candidate = inputPath.startsWith('/') ? normalizeAbsolutePath(inputPath) : joinPath(root, inputPath);
	if (!isAgentWorkspacePathWithinRoot(candidate, root)) {
		throw new AgentWorkspacePathError('路径超出工作区根目录。', 'outside-root');
	}
	return candidate;
}

export function isAgentWorkspacePathWithinRoot(path: string, rootPath: string): boolean {
	const root = normalizeAgentWorkspaceRoot(rootPath);
	const candidate = normalizeAbsolutePath(path);
	return root === '/' || candidate === root || candidate.startsWith(`${root}/`);
}

export function validateAgentWorkspaceBasename(name: string): string {
	if (
		!name ||
		name === '.' ||
		name === '..' ||
		name.includes('/') ||
		name.includes('\\') ||
		name.includes('\0') ||
		utf8Bytes(name) > maxWorkspaceNameBytes
	) {
		throw new AgentWorkspacePathError('文件系统返回了无效名称。', 'invalid-name');
	}
	return name;
}

export function joinAgentWorkspaceEntryPath(directory: string, name: string): string {
	const basename = validateAgentWorkspaceBasename(name);
	return directory === '/' ? `/${basename}` : `${directory}/${basename}`;
}

function joinPath(root: string, relative: string): string {
	return normalizeAbsolutePath(root === '/' ? `/${relative}` : `${root}/${relative}`);
}

function normalizeAbsolutePath(path: string): string {
	if (!path.startsWith('/') || path.includes('\\') || path.includes('\0')) {
		throw new AgentWorkspacePathError('工作区路径无效。', 'invalid-path');
	}
	const segments: string[] = [];
	for (const segment of path.split('/')) {
		if (!segment || segment === '.') continue;
		if (segment === '..') segments.pop();
		else segments.push(segment);
	}
	const normalized = `/${segments.join('/')}`;
	if (utf8Bytes(normalized) > maxWorkspacePathBytes) {
		throw new AgentWorkspacePathError('工作区路径过长。', 'invalid-path');
	}
	return normalized;
}

function utf8Bytes(value: string): number {
	return new TextEncoder().encode(value).byteLength;
}

import { getSkillIdentity, type Skill } from '@wener/ai/agent/skill';
import { resolveAgentWorkspacePath } from './workspace-path';
import {
	type AgentWorkspaceContext,
	type AgentWorkspaceContextIssue,
	type AgentWorkspaceContextLimits,
	defaultAgentWorkspaceContextLimits,
	type LoadAgentWorkspaceContextOptions,
} from './workspace-types';

export async function loadAgentWorkspaceContext({
	agentsPath = 'AGENTS.md',
	limits: inputLimits,
	signal,
	skills,
	workspace,
}: LoadAgentWorkspaceContextOptions): Promise<AgentWorkspaceContext> {
	const limits = resolveContextLimits(inputLimits);
	throwIfAborted(signal);
	const issues: AgentWorkspaceContextIssue[] = [];
	let aggregateBytes = 0;
	let agents: AgentWorkspaceContext['agents'];
	const resolvedAgentsPath = resolveAgentWorkspacePath(workspace.rootPath, agentsPath);
	try {
		const bytes = await workspace.fileSystem.readFile(resolvedAgentsPath, {
			encoding: 'binary',
			maxBytes: limits.maxAgentsBytes + 1,
			signal,
		});
		throwIfAborted(signal);
		if (bytes.byteLength > limits.maxAgentsBytes) {
			issues.push({
				code: 'agents-too-large',
				message: `AGENTS 文件超过 ${limits.maxAgentsBytes} 字节，已整体排除。`,
				path: resolvedAgentsPath,
			});
		} else if (bytes.byteLength > limits.maxAggregateBytes) {
			issues.push({
				code: 'aggregate-too-large',
				message: 'AGENTS 文件超过工作区上下文总量限制，已整体排除。',
				path: resolvedAgentsPath,
			});
		} else {
			const content = decodeUtf8(bytes, resolvedAgentsPath, issues);
			if (content !== undefined) {
				aggregateBytes += bytes.byteLength;
				agents = { bytes: bytes.byteLength, content, path: resolvedAgentsPath };
			}
		}
	} catch (error) {
		if (isAbortError(error) || signal?.aborted) throw createAbortError();
		if (!isNotFoundError(error)) {
			issues.push({
				code: 'agents-read-failed',
				message: `读取 AGENTS 文件失败：${toErrorMessage(error)}`,
				path: resolvedAgentsPath,
			});
		}
	}

	const selectedSkills: AgentWorkspaceContext['skills'] = [];
	if (skills.length > limits.maxSkills) {
		issues.push({
			code: 'skill-count-exceeded',
			message: `最多加载 ${limits.maxSkills} 个 Skill，其余已排除。`,
		});
	}
	for (const skill of skills.slice(0, limits.maxSkills)) {
		throwIfAborted(signal);
		const descriptionBytes = utf8Bytes(skill.description);
		const instructionBytes = utf8Bytes(skill.instructions);
		const bytes = descriptionBytes + instructionBytes;
		if (descriptionBytes > limits.maxSkillBytes || instructionBytes > limits.maxSkillBytes) {
			issues.push(
				skillIssue('skill-too-large', skill, `Skill 的描述或指令超过 ${limits.maxSkillBytes} 字节，已整体排除。`),
			);
			continue;
		}
		if (aggregateBytes + bytes > limits.maxAggregateBytes) {
			issues.push(skillIssue('aggregate-too-large', skill, 'Skill 超过工作区上下文总量限制，已整体排除。'));
			continue;
		}
		aggregateBytes += bytes;
		selectedSkills.push({
			bytes,
			description: skill.description,
			identity: getSkillIdentity(skill),
			instructions: skill.instructions,
			name: skill.name,
			version: skill.version,
		});
	}
	throwIfAborted(signal);
	return {
		agents,
		bytes: aggregateBytes,
		issues,
		skills: selectedSkills,
		workspaceId: workspace.id,
		workspaceRevision: workspace.revision,
	};
}

function resolveContextLimits(input?: Partial<AgentWorkspaceContextLimits>): AgentWorkspaceContextLimits {
	const limits = { ...defaultAgentWorkspaceContextLimits, ...input };
	for (const [name, value] of Object.entries(limits)) {
		if (!Number.isSafeInteger(value) || value <= 0) throw new Error(`${name} 必须是正整数。`);
	}
	return limits;
}

function skillIssue(
	code: 'aggregate-too-large' | 'skill-too-large',
	skill: Skill,
	message: string,
): AgentWorkspaceContextIssue {
	return { code, message, skillIdentity: getSkillIdentity(skill), skillName: skill.name };
}

function decodeUtf8(bytes: Uint8Array, path: string, issues: AgentWorkspaceContextIssue[]): string | undefined {
	try {
		return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
	} catch {
		issues.push({ code: 'invalid-text', message: 'AGENTS 文件不是有效的 UTF-8 文本，已整体排除。', path });
		return undefined;
	}
}

function isNotFoundError(error: unknown): boolean {
	return typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT';
}

function isAbortError(error: unknown): boolean {
	return error instanceof DOMException
		? error.name === 'AbortError'
		: error instanceof Error && error.name === 'AbortError';
}

function throwIfAborted(signal?: AbortSignal): void {
	if (signal?.aborted) throw createAbortError();
}

function createAbortError(): Error {
	return typeof DOMException === 'function'
		? new DOMException('上下文加载已取消。', 'AbortError')
		: Object.assign(new Error('上下文加载已取消。'), { name: 'AbortError' });
}

function toErrorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function utf8Bytes(value: string): number {
	return new TextEncoder().encode(value).byteLength;
}

import { FileSystemError, type IFileSystem } from '@wener/common/fs';

export function createAgentWorkspaceMutationGuard(fileSystem: IFileSystem, canMutate: () => boolean): IFileSystem {
	const assertMutationAllowed = () => {
		if (!canMutate()) throw new FileSystemError('Workspace mutations are quarantined', 'EPERM');
	};
	return {
		copy: async (...args) => {
			assertMutationAllowed();
			await fileSystem.copy(...args);
		},
		createReadableStream: fileSystem.createReadableStream?.bind(fileSystem),
		createWritableStream: fileSystem.createWritableStream
			? (...args) => {
					assertMutationAllowed();
					const writer = fileSystem.createWritableStream!(...args).getWriter();
					return new WritableStream({
						abort: (reason) => writer.abort(reason),
						close: async () => {
							try {
								assertMutationAllowed();
								await writer.close();
							} catch (error) {
								await writer.abort(error).catch(() => undefined);
								throw error;
							}
						},
						write: async (chunk) => {
							try {
								assertMutationAllowed();
								await writer.write(chunk);
							} catch (error) {
								await writer.abort(error).catch(() => undefined);
								throw error;
							}
						},
					});
				}
			: undefined,
		exists: (...args) => fileSystem.exists(...args),
		getUrl: fileSystem.getUrl?.bind(fileSystem),
		mkdir: async (...args) => {
			assertMutationAllowed();
			await fileSystem.mkdir(...args);
		},
		readFile: fileSystem.readFile.bind(fileSystem),
		readdir: (...args) => fileSystem.readdir(...args),
		rename: async (...args) => {
			assertMutationAllowed();
			await fileSystem.rename(...args);
		},
		rm: async (...args) => {
			assertMutationAllowed();
			await fileSystem.rm(...args);
		},
		stat: (...args) => fileSystem.stat(...args),
		writeFile: async (...args) => {
			assertMutationAllowed();
			await fileSystem.writeFile(...args);
		},
	};
}

import type { Persona } from '@wener/ai/agent/persona';
import type { AgentWorkspaceContext, AgentWorkspaceContextIssue } from './workspace-types';

export const AgentInstructionSeparator = '\n\n---\n\n';
export const defaultAgentInstructionMaxBytes = 256 * 1024;

export type ComposeAgentInstructionsOptions = {
	context?: AgentWorkspaceContext;
	maxBytes?: number;
	persona?: Persona;
};

export type ComposedAgentInstructions = {
	bytes: number;
	included: Array<'agents' | 'persona' | `skill:${string}`>;
	instructions: string;
	issues: AgentWorkspaceContextIssue[];
};

export function composeAgentInstructions({
	context,
	maxBytes = defaultAgentInstructionMaxBytes,
	persona,
}: ComposeAgentInstructionsOptions): ComposedAgentInstructions {
	if (!Number.isSafeInteger(maxBytes) || maxBytes <= 0) throw new Error('指令总量限制必须是正整数。');
	const sections: string[] = [];
	const included: ComposedAgentInstructions['included'] = [];
	const issues = [...(context?.issues ?? [])];
	let bytes = 0;
	const append = (kind: ComposedAgentInstructions['included'][number], content: string, label: string) => {
		if (!content.trim()) return;
		const section = `## ${label}\n\n${content.trim()}`;
		const addition = `${sections.length ? AgentInstructionSeparator : ''}${section}`;
		const additionBytes = utf8Bytes(addition);
		if (bytes + additionBytes > maxBytes) {
			issues.push({ code: 'aggregate-too-large', message: `${label} 超过指令总量限制，已整体排除。` });
			return;
		}
		sections.push(section);
		included.push(kind);
		bytes += additionBytes;
	};

	if (persona) append('persona', composePersona(persona), `Persona: ${persona.name}`);
	if (context?.agents) append('agents', context.agents.content, `AGENTS: ${context.agents.path}`);
	for (const skill of context?.skills ?? []) {
		append(
			`skill:${skill.identity}`,
			`描述：${skill.description}\n\n指令：\n${skill.instructions}`,
			`Skill: ${skill.name}@${skill.version}`,
		);
	}
	return { bytes, included, instructions: sections.join(AgentInstructionSeparator), issues };
}

function composePersona(persona: Persona): string {
	const parts: string[] = [];
	appendLabeled(parts, '描述', persona.description);
	appendLabeled(parts, 'System', persona.prompts?.system);
	appendLabeled(parts, 'Persona', persona.prompts?.persona);
	appendLabeled(parts, '场景', persona.prompts?.scenario);
	appendLabeled(parts, '对话后指令', persona.prompts?.postHistoryInstructions);
	appendLabeled(parts, '背景', persona.authoring?.background);
	appendLabeled(parts, '性格', persona.authoring?.personality);
	appendLabeled(parts, '行为策略', persona.authoring?.behaviorPolicy);
	appendLabeled(parts, '表达风格', persona.authoring?.speechStyle);
	if (persona.authoring?.values?.length) parts.push(`价值观：${persona.authoring.values.join('；')}`);
	if (persona.authoring?.goals?.length) parts.push(`目标：${persona.authoring.goals.join('；')}`);
	return parts.join('\n\n');
}

function appendLabeled(target: string[], label: string, value?: string): void {
	if (value?.trim()) target.push(`${label}：${value.trim()}`);
}

function utf8Bytes(value: string): number {
	return new TextEncoder().encode(value).byteLength;
}

import { type ToolSet, tool } from 'ai';
import { z } from 'zod';
import {
	joinAgentWorkspaceEntryPath,
	resolveAgentWorkspacePath,
	validateAgentWorkspaceBasename,
} from './workspace-path';
import type { AgentWorkspace } from './workspace-types';

export const MaxAgentWorkspaceListEntries = 200;
export const MaxAgentWorkspaceListOutputBytes = 64 * 1024;
export const MaxAgentWorkspaceReadBytes = 64 * 1024;

export function createAgentWorkspaceReadTools(workspace: AgentWorkspace): ToolSet {
	return {
		workspace_list: tool({
			description: '列出工作区根目录内的文件和目录。',
			inputSchema: z.object({ path: z.string().max(4096).default('.') }),
			execute: async ({ path }, { abortSignal }) => listWorkspace(workspace, path, abortSignal),
		}),
		workspace_read: tool({
			description: '读取工作区根目录内不超过 64 KiB 的 UTF-8 文件。',
			inputSchema: z.object({ path: z.string().min(1).max(4096) }),
			execute: async ({ path }, { abortSignal }) => readWorkspace(workspace, path, abortSignal),
		}),
	};
}

async function listWorkspace(workspace: AgentWorkspace, inputPath: string, signal?: AbortSignal) {
	try {
		const path = resolveAgentWorkspacePath(workspace.rootPath, inputPath);
		const rawEntries = await workspace.fileSystem.readdir(path, {
			maxEntries: MaxAgentWorkspaceListEntries,
			signal,
		});
		const entries: Array<{ kind: 'directory' | 'file'; name: string; size: number }> = [];
		const seen = new Set<string>();
		let invalidEntries = 0;
		let truncated = rawEntries.length > MaxAgentWorkspaceListEntries;
		for (const raw of rawEntries.slice(0, MaxAgentWorkspaceListEntries)) {
			if (entries.length >= MaxAgentWorkspaceListEntries) break;
			try {
				const name = validateAgentWorkspaceBasename(raw.name);
				joinAgentWorkspaceEntryPath(path, name);
				if (seen.has(name) || (raw.kind !== 'directory' && raw.kind !== 'file')) throw new Error('invalid entry');
				seen.add(name);
				const next = { kind: raw.kind, name, size: safeSize(raw.size) };
				const candidate = { entries: [...entries, next], invalidEntries, ok: true, path, truncated };
				if (jsonBytes(candidate) > MaxAgentWorkspaceListOutputBytes) {
					truncated = true;
					break;
				}
				entries.push(next);
			} catch {
				invalidEntries += 1;
			}
		}
		entries.sort((left, right) => left.name.localeCompare(right.name));
		return { entries, invalidEntries, ok: true as const, path, truncated };
	} catch (error) {
		return toolError(error);
	}
}

async function readWorkspace(workspace: AgentWorkspace, inputPath: string, signal?: AbortSignal) {
	try {
		const path = resolveAgentWorkspacePath(workspace.rootPath, inputPath);
		const content = await workspace.fileSystem.readFile(path, {
			encoding: 'binary',
			maxBytes: MaxAgentWorkspaceReadBytes + 1,
			signal,
		});
		if (content.byteLength > MaxAgentWorkspaceReadBytes) {
			return { code: 'too-large' as const, limitBytes: MaxAgentWorkspaceReadBytes, ok: false as const, path };
		}
		try {
			return {
				bytes: content.byteLength,
				content: new TextDecoder('utf-8', { fatal: true }).decode(content),
				ok: true as const,
				path,
			};
		} catch {
			return { code: 'binary' as const, ok: false as const, path };
		}
	} catch (error) {
		return toolError(error);
	}
}

function toolError(error: unknown) {
	if (error instanceof Error && error.name === 'AbortError') return { code: 'aborted' as const, ok: false as const };
	const code =
		typeof error === 'object' && error !== null && 'code' in error ? String(error.code).slice(0, 64) : 'failed';
	return { code, message: toErrorMessage(error).slice(0, 256), ok: false as const };
}

function toErrorMessage(error: unknown): string {
	return error instanceof Error ? error.message : '工作区操作失败。';
}

function jsonBytes(value: unknown): number {
	return new TextEncoder().encode(JSON.stringify(value)).byteLength;
}

function safeSize(value: number): number {
	return Number.isSafeInteger(value) && value >= 0 ? value : 0;
}

'use client';

import type { Skill } from '@wener/ai/agent/skill';
import { useEffect, useRef, useState } from 'react';
import { loadAgentWorkspaceContext } from './workspace-context';
import type { AgentWorkspace, AgentWorkspaceContext, AgentWorkspaceContextLimits } from './workspace-types';

export type UseAgentWorkspaceContextOptions = {
	agentsPath?: string;
	enabled?: boolean;
	limits?: Partial<AgentWorkspaceContextLimits>;
	skills: readonly Skill[];
	workspace: AgentWorkspace;
};

export type AgentWorkspaceContextState = {
	context?: AgentWorkspaceContext;
	error?: Error;
	status: 'error' | 'idle' | 'loading' | 'ready';
};

export function useAgentWorkspaceContext(options: UseAgentWorkspaceContextOptions): AgentWorkspaceContextState {
	const [state, setState] = useState<AgentWorkspaceContextState>({
		status: options.enabled === false ? 'idle' : 'loading',
	});
	const stableOptions = useStableContextOptions(options);
	useEffect(() => {
		if (stableOptions.enabled === false) {
			setState({ status: 'idle' });
			return;
		}
		const controller = new AbortController();
		let current = true;
		setState({ status: 'loading' });
		void loadAgentWorkspaceContext({ ...stableOptions, signal: controller.signal }).then(
			(context) => {
				if (current && !controller.signal.aborted) setState({ context, status: 'ready' });
			},
			(error: unknown) => {
				if (current && !controller.signal.aborted) {
					setState({ error: error instanceof Error ? error : new Error(String(error)), status: 'error' });
				}
			},
		);
		return () => {
			current = false;
			controller.abort();
		};
	}, [stableOptions]);
	return state;
}

function useStableContextOptions(options: UseAgentWorkspaceContextOptions): UseAgentWorkspaceContextOptions {
	const stable = useRef(options);
	if (!sameContextOptions(stable.current, options)) stable.current = options;
	return stable.current;
}

function sameContextOptions(left: UseAgentWorkspaceContextOptions, right: UseAgentWorkspaceContextOptions): boolean {
	return (
		left.agentsPath === right.agentsPath &&
		left.enabled === right.enabled &&
		left.workspace.id === right.workspace.id &&
		left.workspace.fileSystem === right.workspace.fileSystem &&
		left.workspace.rootPath === right.workspace.rootPath &&
		left.workspace.revision === right.workspace.revision &&
		sameLimits(left.limits, right.limits) &&
		left.skills.length === right.skills.length &&
		left.skills.every((skill, index) => skill === right.skills[index])
	);
}

function sameLimits(
	left: Partial<AgentWorkspaceContextLimits> | undefined,
	right: Partial<AgentWorkspaceContextLimits> | undefined,
): boolean {
	return (
		left?.maxAgentsBytes === right?.maxAgentsBytes &&
		left?.maxAggregateBytes === right?.maxAggregateBytes &&
		left?.maxSkillBytes === right?.maxSkillBytes &&
		left?.maxSkills === right?.maxSkills
	);
}

'use client';

import { Files, MessagesSquare } from 'lucide-react';
import {
	type ComponentPropsWithRef,
	type KeyboardEvent,
	type ReactNode,
	useEffect,
	useId,
	useMemo,
	useRef,
	useState,
} from 'react';
import { FileManager, type FileManagerProps } from '@/components/file-manager/file-manager';
import { createFileManagerStore } from '@/components/file-manager/file-manager-store';
import type { FileManagerStore } from '@/components/file-manager/file-manager-types';
import { cn } from '@/lib/utils';
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from '../../ui/resizable';
import type { AgentWorkspace, AgentWorkspaceContext } from './workspace-types';

export type AgentWorkPane = 'chat' | 'workspace';

export type AgentWorkTab = {
	id: string;
	label: ReactNode;
	panel: ReactNode;
};

export type AgentWorkMessages = {
	chatPane: string;
	contextTab: string;
	filesTab: string;
	workspacePane: string;
};

export const defaultAgentWorkMessages: AgentWorkMessages = {
	chatPane: '对话',
	contextTab: '上下文',
	filesTab: '文件',
	workspacePane: '工作区',
};

export type AgentWorkProps = ComponentPropsWithRef<'section'> & {
	chat: ReactNode;
	context?: AgentWorkspaceContext;
	defaultPane?: AgentWorkPane;
	defaultWorkspaceTab?: string;
	extraWorkspaceTabs?: readonly AgentWorkTab[];
	fileManagerProps?: Omit<FileManagerProps, 'fileSystem' | 'rootPath'>;
	messages?: Partial<AgentWorkMessages>;
	onPaneChange?: (pane: AgentWorkPane) => void;
	onWorkspaceTabChange?: (tab: string) => void;
	pane?: AgentWorkPane;
	workspace: AgentWorkspace;
	workspaceTab?: string;
	workspaceReadOnly?: boolean;
};

export function AgentWork({
	chat,
	className,
	context,
	defaultPane = 'chat',
	defaultWorkspaceTab = 'files',
	extraWorkspaceTabs = [],
	fileManagerProps,
	messages,
	onPaneChange,
	onWorkspaceTabChange,
	pane,
	workspace,
	workspaceTab,
	workspaceReadOnly = false,
	...props
}: AgentWorkProps) {
	const copy = { ...defaultAgentWorkMessages, ...messages };
	const rootRef = useRef<HTMLElement>(null);
	const [narrow, setNarrow] = useState(false);
	const [localPane, setLocalPane] = useState<AgentWorkPane>(defaultPane);
	const [localTab, setLocalTab] = useState(defaultWorkspaceTab);
	const visiblePane = pane ?? localPane;
	const visibleTab = workspaceTab ?? localTab;
	const fileStore = useAgentWorkFileStore(workspace, fileManagerProps?.store);
	const tabs = useMemo<AgentWorkTab[]>(
		() => [
			{
				id: 'files',
				label: copy.filesTab,
				panel: (
					<FileManager
						{...fileManagerProps}
						className={cn('size-full min-h-0 rounded-none border-0', fileManagerProps?.className)}
						fileSystem={workspace.fileSystem}
						rootPath={workspace.rootPath}
						readOnly={workspaceReadOnly || fileManagerProps?.readOnly}
						showHeader={false}
						store={fileStore}
					/>
				),
			},
			{ id: 'context', label: copy.contextTab, panel: <AgentWorkContextPanel context={context} /> },
			...extraWorkspaceTabs,
		],
		[
			context,
			copy.contextTab,
			copy.filesTab,
			extraWorkspaceTabs,
			fileManagerProps,
			fileStore,
			workspace,
			workspaceReadOnly,
		],
	);
	const activeTab = tabs.find((tab) => tab.id === visibleTab) ?? tabs[0];

	useEffect(() => {
		const element = rootRef.current;
		if (!element) return;
		const update = () => setNarrow(element.getBoundingClientRect().width < 768);
		update();
		if (typeof ResizeObserver !== 'function') return;
		const observer = new ResizeObserver(update);
		observer.observe(element);
		return () => observer.disconnect();
	}, []);

	const selectPane = (next: AgentWorkPane) => {
		if (pane === undefined) setLocalPane(next);
		onPaneChange?.(next);
	};
	const selectTab = (next: string) => {
		if (workspaceTab === undefined) setLocalTab(next);
		onWorkspaceTabChange?.(next);
	};
	const workspacePanel = (
		<AgentWorkspacePanel activeTab={activeTab.id} tabs={tabs} onTabChange={selectTab}>
			{activeTab.panel}
		</AgentWorkspacePanel>
	);

	return (
		<section
			ref={rootRef}
			data-layout={narrow ? 'narrow' : 'wide'}
			data-slot='agent-work'
			className={cn(
				'border-border bg-background text-foreground flex size-full min-h-[32rem] min-w-0 flex-col overflow-hidden rounded-md border',
				className,
			)}
			{...props}
		>
			{narrow ? (
				<>
					<div className='border-border bg-muted/30 flex shrink-0 items-center justify-center border-b p-2'>
						<fieldset className='join min-w-0 border-0 p-0'>
							<legend className='sr-only'>工作模式面板</legend>
							<PaneButton active={visiblePane === 'chat'} icon={<MessagesSquare />} onClick={() => selectPane('chat')}>
								{copy.chatPane}
							</PaneButton>
							<PaneButton active={visiblePane === 'workspace'} icon={<Files />} onClick={() => selectPane('workspace')}>
								{copy.workspacePane}
							</PaneButton>
						</fieldset>
					</div>
					<div className='min-h-0 flex-1'>{visiblePane === 'chat' ? chat : workspacePanel}</div>
				</>
			) : (
				<ResizablePanelGroup orientation='horizontal'>
					<ResizablePanel defaultSize='55%' minSize='30%'>
						<div className='size-full min-h-0'>{chat}</div>
					</ResizablePanel>
					<ResizableHandle withHandle />
					<ResizablePanel defaultSize='45%' minSize='28%'>
						{workspacePanel}
					</ResizablePanel>
				</ResizablePanelGroup>
			)}
		</section>
	);
}

function AgentWorkspacePanel({
	activeTab,
	children,
	onTabChange,
	tabs,
}: {
	activeTab: string;
	children: ReactNode;
	onTabChange: (tab: string) => void;
	tabs: readonly AgentWorkTab[];
}) {
	const tabPanelId = useId();
	const tabRefs = useRef(new Map<string, HTMLButtonElement>());
	const activeIndex = Math.max(
		0,
		tabs.findIndex((tab) => tab.id === activeTab),
	);
	const activeTabId = `${tabPanelId}-tab-${activeIndex}`;
	const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
		let nextIndex = index;
		if (event.key === 'ArrowRight') nextIndex = (index + 1) % tabs.length;
		else if (event.key === 'ArrowLeft') nextIndex = (index - 1 + tabs.length) % tabs.length;
		else if (event.key === 'Home') nextIndex = 0;
		else if (event.key === 'End') nextIndex = tabs.length - 1;
		else return;
		event.preventDefault();
		const next = tabs[nextIndex];
		if (!next) return;
		onTabChange(next.id);
		tabRefs.current.get(next.id)?.focus();
	};
	return (
		<section className='flex size-full min-h-0 min-w-0 flex-col' aria-label='工作区面板'>
			<div
				className='tabs tabs-border border-border min-h-11 shrink-0 border-b px-2'
				role='tablist'
				aria-label='工作区视图'
			>
				{tabs.map((tab, index) => (
					<button
						key={tab.id}
						id={`${tabPanelId}-tab-${index}`}
						ref={(element) => {
							if (element) tabRefs.current.set(tab.id, element);
							else tabRefs.current.delete(tab.id);
						}}
						type='button'
						role='tab'
						aria-controls={tabPanelId}
						aria-selected={activeTab === tab.id}
						tabIndex={activeTab === tab.id ? 0 : -1}
						className={cn('tab min-h-10', activeTab === tab.id && 'tab-active')}
						onKeyDown={(event) => handleKeyDown(event, index)}
						onClick={() => onTabChange(tab.id)}
					>
						{tab.label}
					</button>
				))}
			</div>
			<div id={tabPanelId} role='tabpanel' aria-labelledby={activeTabId} className='min-h-0 flex-1'>
				{children}
			</div>
		</section>
	);
}

function AgentWorkContextPanel({ context }: { context?: AgentWorkspaceContext }) {
	if (!context) return <div className='text-muted-foreground p-4 text-sm'>尚未加载工作区上下文。</div>;
	return (
		<div data-slot='agent-work-context' className='size-full min-h-0 overflow-auto'>
			<header className='border-border border-b px-4 py-3'>
				<h2 className='text-sm font-semibold'>工作区上下文</h2>
				<p className='text-muted-foreground mt-1 text-xs'>{context.bytes} 字节</p>
			</header>
			{context.agents ? (
				<section className='border-border border-b px-4 py-3'>
					<h3 className='text-xs font-semibold'>{context.agents.path}</h3>
					<pre className='bg-muted mt-2 max-h-64 overflow-auto rounded-sm p-3 text-xs whitespace-pre-wrap'>
						{context.agents.content}
					</pre>
				</section>
			) : null}
			{context.skills.map((skill) => (
				<section key={skill.identity} className='border-border border-b px-4 py-3'>
					<h3 className='text-xs font-semibold'>
						{skill.name}@{skill.version}
					</h3>
					<p className='text-muted-foreground mt-1 text-xs'>{skill.description}</p>
					<pre className='bg-muted mt-2 max-h-56 overflow-auto rounded-sm p-3 text-xs whitespace-pre-wrap'>
						{skill.instructions}
					</pre>
				</section>
			))}
			{context.issues.length ? (
				<section aria-label='上下文问题' className='px-4 py-3'>
					<h3 className='text-warning text-xs font-semibold'>上下文问题</h3>
					<ul className='mt-2 space-y-1 text-xs'>
						{context.issues.map((issue, index) => (
							<li key={`${issue.code}:${issue.path ?? issue.skillIdentity ?? issue.skillName ?? index}`}>
								{issue.message}
							</li>
						))}
					</ul>
				</section>
			) : null}
		</div>
	);
}

function PaneButton({
	active,
	children,
	icon,
	onClick,
}: {
	active: boolean;
	children: ReactNode;
	icon: ReactNode;
	onClick: () => void;
}) {
	return (
		<button
			type='button'
			className={cn('btn btn-sm join-item min-w-28', active ? 'btn-neutral' : 'btn-ghost')}
			aria-pressed={active}
			onClick={onClick}
		>
			<span aria-hidden='true' className='[&>svg]:size-4'>
				{icon}
			</span>
			{children}
		</button>
	);
}

function useAgentWorkFileStore(workspace: AgentWorkspace, supplied?: FileManagerStore): FileManagerStore {
	const [local] = useState(() =>
		createFileManagerStore({ fileSystem: workspace.fileSystem, rootPath: workspace.rootPath }),
	);
	const store = supplied ?? local;
	const identity = useRef({
		fileSystem: workspace.fileSystem,
		id: workspace.id,
		revision: workspace.revision,
		rootPath: workspace.rootPath,
	});
	useEffect(() => {
		const previous = identity.current;
		const backendChanged =
			previous.fileSystem !== workspace.fileSystem ||
			previous.id !== workspace.id ||
			previous.rootPath !== workspace.rootPath;
		identity.current = {
			fileSystem: workspace.fileSystem,
			id: workspace.id,
			revision: workspace.revision,
			rootPath: workspace.rootPath,
		};
		if (backendChanged) store.getState().actions.replaceFileSystem(workspace.fileSystem, workspace.rootPath);
		else if (previous.revision !== workspace.revision) store.getState().actions.refresh();
	}, [store, workspace.fileSystem, workspace.id, workspace.revision, workspace.rootPath]);
	return store;
}

